INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261124-gomez-resigns-ethics-report', 'rep-jimmy-gomez-resign-december-1-house-ethics-committee-report', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 1, 'Rep. Jimmy Gomez says he will resign Dec. 1 after a House Ethics Committee report', 'The committee concluded on Monday, Nov. 23, that the California Democrat violated House rules in his conduct toward a staffer. Gomez disputes the findings.', 'Rep. Jimmy Gomez, a California Democrat who represents parts of Los Angeles, said he will resign from the House effective Tuesday, Dec. 1, after the House Ethics Committee released a report about him on Monday, Nov. 23, NPR reported.

The committee concluded that Gomez violated House rules by making unwelcome sexual advances and engaging in unwelcome sexual conduct toward a House staffer, according to NPR. The report cited substantial evidence and said the conduct could constitute a crime, NPR reported.

## The investigation

The Ethics Committee, which has five Democrats and five Republicans, opened its inquiry in August after a press report described an encounter between Gomez and a staffer from another office at a party, according to NPR. Gomez denied that report at the time.

Attorneys for the staffer issued a statement welcoming the committee''s findings, NPR reported.

## Gomez''s response

Gomez said he cooperated with the investigation but has strong disagreements with the report and its conclusions, according to NPR. He said the report leaves out key parts of his testimony and that he was not given a chance to respond to how his statements were characterized. He denied that any of the interactions were nonconsensual.

## Context

Gomez had already lost his reelection race on Tuesday, Nov. 3, to fellow Democrat Angela Gonzales-Torres under California''s top-two system, NPR reported. The NPR report did not say how the vacancy will be handled.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Skyline_view_of_Los_Angeles,_California_LCCN2013631685_(cropped).tif/lossy-page1-1280px-Skyline_view_of_Los_Angeles,_California_LCCN2013631685_(cropped).tif.jpg', 'Skyline view of Los Angeles (file photo). Carol M. Highsmith Archive, Library of Congress, no known restrictions, via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-24.sql', 8, 0, 'newsroom-assistant', '2026-11-24T11:00:00.000Z', '2026-11-24T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261124-gomez-resigns-ethics-report-src1', 'bd-20261124-gomez-resigns-ethics-report', 'California Democrat Rep. Gomez resigns following ethics report on sexual misconduct allegations', 'https://www.wvxu.org/news-from-npr/2026-11-23/california-democrat-rep-gomez-resigns-following-ethics-report-on-sexual-misconduct-allegations', 'NPR (via WVXU)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-24T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-24. Editor to confirm.', 'newsroom-assistant', '2026-11-24T11:00:00.000Z');
