INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261124-hud-homelessness-ruling', 'judge-mcelroy-hud-overstepped-1-3-billion-continuum-of-care-homelessness-grants', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Federal judge rules HUD overstepped by steering $1.3 billion in homelessness grants away from permanent housing', 'Judge Mary S. McElroy ruled on Friday, Nov. 20, in a case brought by states and cities that include Massachusetts, Boston and Cambridge. HUD says it may appeal.', 'A federal judge in Rhode Island ruled on Friday, Nov. 20, that the Department of Housing and Urban Development exceeded its authority when it set aside $1.3 billion of its roughly $4 billion Continuum of Care homelessness program for new projects that favor transitional housing and supportive services over permanent housing, the Rhode Island Current reported.

U.S. District Judge Mary S. McElroy, who was appointed by President Trump in his first term, issued a 59-page ruling, according to the Rhode Island Current. She wrote that a general clause in the program''s rules could not be read to let HUD override the other factors Congress made mandatory.

## What changes

Grant applicants may amend and resubmit certain applications by Tuesday, Dec. 1, and HUD must evaluate them and award the grants by Thursday, Dec. 31, according to the Rhode Island Current and The Epoch Times. The Epoch Times reported that the ruling left some other incentives in place, including extra points for sober housing and partnerships with outpatient treatment providers.

## Who sued

The plaintiffs include 20 attorneys general, among them Massachusetts, along with the District of Columbia and the governors of Kentucky and Pennsylvania, the Rhode Island Current reported. A separate coalition included the National Alliance to End Homelessness, the National Low Income Housing Coalition and several local governments, including Boston, Cambridge, San Francisco and King County, Washington.

## Reaction

HUD Secretary Scott Turner told the Rhode Island Current that the department reserves the right to appeal and that its "Treatment First" approach will not be deterred. He said the plaintiffs'' agenda threatens to cause gaps in funding.

Rhode Island Attorney General Peter Neronha said the coalition remains committed to holding the administration accountable, according to the Rhode Island Current. The White House did not immediately respond to The Epoch Times.

In August, McElroy set aside HUD''s funding notice for the 2026 cycle in full, and an appeals court paused that order, the Rhode Island Current reported. The ruling on Nov. 20 addresses HUD''s revised approach.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Providence,_the_capital_of,_and_largest_city_in,_Rhode_Island,_is_an_old_city_by_U.S._standards,_but_its_downtown_includes_several_modern_buildings_such_as_these,_viewed_from_a_green_next_to_the_city_railroad_terminal.jpg/1280px-Providence,_the_capital_of,_and_largest_city_in,_Rhode_Island,_is_an_old_city_by_U.S._standards,_but_its_downtown_includes_several_modern_buildings_such_as_these,_viewed_from_a_green_next_to_the_city_railroad_terminal.jpg', 'Downtown Providence, Rhode Island (file photo). Carol M. Highsmith Archive, Library of Congress, no known restrictions, via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-24.sql', 7, 0, 'newsroom-assistant', '2026-11-24T11:00:00.000Z', '2026-11-24T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261124-hud-homelessness-ruling-src1', 'bd-20261124-hud-homelessness-ruling', 'RI federal judge says HUD overstepped authority in latest homelessness funding changes', 'https://www.yahoo.com/news/us/articles/ri-federal-judge-says-hud-213410588.html', 'Rhode Island Current (via Yahoo News)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-24T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-24. Editor to confirm.', 'newsroom-assistant', '2026-11-24T11:00:00.000Z');
