INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261124-sea-tac-ice-arrests', 'ice-arrests-father-daughter-sea-tac-alaska-airlines-jet-bridge-ferguson', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'ICE arrests a father and daughter on a Sea-Tac jet bridge, drawing sharp criticism from Washington leaders', 'Officers detained the two as they boarded an Alaska Airlines flight on Saturday, Nov. 21. DHS says both overstayed visas; Gov. Bob Ferguson said ICE is out of control.', 'Immigration and Customs Enforcement officers arrested two passengers as they boarded an Alaska Airlines flight at Seattle-Tacoma International Airport on Saturday, Nov. 21, CBS News reported. The arrests prompted protests over ICE enforcement tactics, PBS NewsHour reported on Monday, Nov. 23.

The Department of Homeland Security identified the two as Ricardo Larrondo Mendoza and Sofia Hernandez Mejia, Mexican nationals who DHS says overstayed their visas, according to CBS News. A DHS source told CBS they are father and daughter.

## What DHS says

DHS described the arrests as a targeted enforcement operation and said a second passenger threw hot coffee at officers, CBS News reported. DHS said Hernandez Mejia faces a federal charge of assaulting a federal officer.

Immigration attorney Olia Catala said both are being held at the Northwest Processing Center in Tacoma, where she visited them on Sunday night, Nov. 22, according to CBS News.

## The airline and the port

Alaska Airlines said it was concerned by the law enforcement action and that ICE gave no advance notice, CBS News reported. Flight 1306 to Los Angeles was scheduled to leave at 8:45 a.m. and departed at 11:03 a.m. after some crew members asked to be replaced. The Port of Seattle said the arrests were distressing for the family and other passengers and that local authorities would engage federal officials.

## Political reaction

Washington Gov. Bob Ferguson, a Democrat, called ICE "completely and totally out of control," CBS News reported. Democratic Reps. Adam Smith and Pramila Jayapal also criticized the arrests.

CBS News noted DHS figures showing a record 491,000 ICE arrests in fiscal year 2026.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/U.S._Immigration_and_Customs_Enforcement_(ICE)_Enforcement_and_Removal_Operations%27_(ERO)_officers_in_West_Palm_Beach,_Florida_on_February_14,_2025_-_20.jpg/1280px-U.S._Immigration_and_Customs_Enforcement_(ICE)_Enforcement_and_Removal_Operations%27_(ERO)_officers_in_West_Palm_Beach,_Florida_on_February_14,_2025_-_20.jpg', 'ICE Enforcement and Removal Operations officers in West Palm Beach, Fla., Feb. 14, 2025 (file photo, not from the Seattle arrests). U.S. Immigration and Customs Enforcement (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-24.sql', 7, 0, 'newsroom-assistant', '2026-11-24T11:00:00.000Z', '2026-11-24T11:00:00.000Z');
