INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261124-white-house-christmas-tree', 'melania-trump-welcomes-2026-white-house-christmas-tree-wisconsin-concolor-fir', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Melania Trump welcomes the 2026 White House Christmas tree, an 18-foot fir from Wisconsin', 'The concolor fir arrived on Monday, Nov. 23, and will stand in the Blue Room. It is the fourth White House tree from Silent Night Evergreens.', 'First lady Melania Trump welcomed the 2026 White House Christmas tree on Monday, Nov. 23, according to the White House and reporting by FOX 5 DC and ¡HOLA! USA. The 18-foot concolor fir came from Silent Night Evergreens in Endeavor, Wisconsin, and will stand in the Blue Room for the holiday season.

The first lady called it a beautiful tree and said she was thankful for family and health, ¡HOLA! USA reported.

## The tree''s journey

FOX 5 DC, citing the Office of the First Lady, reported that the tree was scheduled to arrive at noon on the North Drive and was transported by Chuck Jensen, a 10-year Army veteran and FedEx Freight driver.

Officials selected the tree on Sept. 21 after Silent Night Evergreens won the National Christmas Tree Association''s national contest, FOX 5 DC reported. The farm also supplied White House trees in 1998, 2003 and 2017.

## What comes next

¡HOLA! USA, citing Page Six, reported that the interior decorating theme, "American Bloom," will be unveiled shortly after Thanksgiving. No date has been announced.

The same day, the first lady and second lady Usha Vance attended a Red Cross care-package event at Joint Base Andrews, according to ¡HOLA! USA.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/2019_White_House_Christmas_(49193200363).jpg/1280px-2019_White_House_Christmas_(49193200363).jpg', 'White House Christmas decorations, 2019 (file photo). Official White House photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-24.sql', 5, 0, 'newsroom-assistant', '2026-11-24T11:00:00.000Z', '2026-11-24T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261124-white-house-christmas-tree-src1', 'bd-20261124-white-house-christmas-tree', 'First Lady Melania Trump Welcomes the 2026 White House Christmas Tree: A Timeless American Tradition', 'https://www.whitehouse.gov/videos/first-lady-melania-trump-welcomes-the-2026-white-house-christmas-tree-a-timeless-american-tradition/', 'The White House', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-24T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-24. Editor to confirm.', 'newsroom-assistant', '2026-11-24T11:00:00.000Z');
