INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261124-commanders-stun-bengals-mnf', 'commanders-beat-bengals-22-20-monday-night-football-drew-stevens-field-goal-jayden-daniels', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Commanders stun Bengals 22-20 on Drew Stevens'' late field goal on Monday Night Football', 'Jayden Daniels drove Washington 64 yards in four plays without a timeout after Cincinnati took the lead with 46 seconds left on Monday, Nov. 23, ending the Bengals'' five-game winning streak.', 'The Washington Commanders beat the Cincinnati Bengals 22-20 on Monday, Nov. 23, at Northwest Stadium in Landover, Maryland, on a 26-yard field goal by rookie kicker Drew Stevens, according to the Bengals and NBC.

## The finish

Cincinnati took a 20-19 lead on a 56-yard field goal by Evan McPherson with 46 seconds left, the Bengals reported. Washington, with no timeouts, then went 64 yards in four plays. Jayden Daniels completed two deep throws to rookie receiver Antonio Williams to set up the winning kick, according to the Bengals'' recap.

## The numbers

Joe Burrow completed 28 of 40 passes for 300 yards and two touchdowns for Cincinnati, both sources reported. Williams caught nine passes for 122 yards, and Stevens made all five of his field goal attempts, NBC reported. The Bengals said Boye Mafe had three sacks in the first half.

## Where they stand

The loss ended a five-game winning streak for Cincinnati, which fell to 7-3. Washington improved to 4-5-1, NBC reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Army_vs._Navy_football_game_131214-A-GQ805-445.jpg/1280px-Army_vs._Navy_football_game_131214-A-GQ805-445.jpg', 'Army vs. Navy football game, Dec. 14, 2013 (file photo, not from this game). U.S. Army photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-24.sql', 7, 0, 'newsroom-assistant', '2026-11-24T11:00:00.000Z', '2026-11-24T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261124-commanders-stun-bengals-mnf-src1', 'bd-20261124-commanders-stun-bengals-mnf', 'Winners, losers as Commanders stun Bengals 22-20 on Monday Night Football', 'https://www.nbclosangeles.com/news/sports/nfl/commanders-bengals-score-joe-burrow-jayden-daniels/3974522/', 'NBC Los Angeles (NBC Sports)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-24T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-24. Editor to confirm.', 'newsroom-assistant', '2026-11-24T11:00:00.000Z');
