INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261124-skubal-mets-450-million', 'tarik-skubal-agrees-nine-year-450-million-contract-new-york-mets', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Tarik Skubal agrees to a nine-year, $450 million deal with the Mets, a record for a pitcher', 'The two-time Cy Young Award winner reached agreement on Sunday, Nov. 22, according to reports cited by CBS Sports. The deal includes a full no-trade clause.', 'Two-time Cy Young Award winner Tarik Skubal has agreed to a nine-year, $450 million contract with the New York Mets, CBS Sports reported on Sunday, Nov. 22, citing the New York Post.

The deal includes a $45 million signing bonus and no options or opt-outs, according to SNY, as cited by CBS Sports. CBS Sports also reported that Skubal will have a full no-trade clause.

## A record for a pitcher

Once finalized, the agreement would be the largest ever for a pitcher, passing the $325 million deal Yoshinobu Yamamoto signed with the Los Angeles Dodgers, according to CBS Sports. Yamamoto''s 12-year term remains the longest for a pitcher.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Mets_Visit_Bethesda_USO_(4607115).jpg/1280px-Mets_Visit_Bethesda_USO_(4607115).jpg', 'New York Mets players visit the USO in Bethesda, Md. (file photo). U.S. Department of Defense (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-24.sql', 6, 0, 'newsroom-assistant', '2026-11-24T11:00:00.000Z', '2026-11-24T11:00:00.000Z');
